// All database-specific backup and restore operations stay in the DB package.
import Dexie, { type IndexableType } from 'dexie';
import { db } from './db/index.js';
import { shouldIncludeBackupTable } from './backup.js';

export const BACKUP_DB_BATCH = 20;
// Archives generated by earlier versions may contain 100-row frames.
const MAX_RESTORE_DB_BATCH = 100;
export const BACKUP_DB_SCHEMA = () => db.verno;
export const backupTableNames = (): string[] =>
  db.tables.filter(({ name }) => shouldIncludeBackupTable(name)).map(({ name }) => name);

export interface BackupRows {
  tableName: string;
  rows: unknown[];
}

/** Count rows via indexed stores, without materializing them, for real progress. */
export async function countBackupRows(signal?: AbortSignal): Promise<Record<string, number>> {
  const counts: Record<string, number> = {};
  for (const name of backupTableNames()) {
    if (signal?.aborted) throw new DOMException('Operation cancelled', 'AbortError');
    counts[name] = await db.table(name).count();
  }
  return counts;
}

/** Cursor batches, NOT a full-table .toArray(). offset is deliberately avoided. */
export async function* readBackupRows(signal?: AbortSignal): AsyncGenerator<BackupRows> {
  for (const tableName of backupTableNames()) {
    const table = db.table(tableName);
    let lastKey: IndexableType | undefined;
    let hasRows = false;
    while (true) {
      if (signal?.aborted) throw new DOMException('Operation cancelled', 'AbortError');
      const collection = lastKey === undefined ? table.orderBy(':id') : table.where(':id').above(lastKey);
      // Reading primary keys together with rows supports out-of-line key stores.
      const [rows, keys] = await Promise.all([
        collection.limit(BACKUP_DB_BATCH).toArray(),
        collection.limit(BACKUP_DB_BATCH).primaryKeys()
      ]);
      if (!rows.length) break;
      lastKey = keys[keys.length - 1];
      hasRows = true;
      yield { tableName, rows };
      if (rows.length < BACKUP_DB_BATCH) break;
    }
    // An empty table must still be represented so absence is detectable.
    if (!hasRows) yield { tableName, rows: [] };
  }
}

export function validateRestoreTableNames(names: readonly string[]): void {
  if (!Array.isArray(names) || !names.length || !names.includes('settings') ||
      new Set(names).size !== names.length ||
      names.some((name) => typeof name !== 'string' || name === 'backupStaging' || !db.tables.some((t) => t.name === name))) {
    throw new Error('Backup is missing essential tables or contains unknown tables.');
  }
}

export function validateRestoreRows(tableName: string, rows: unknown[]): void {
  const table = db.tables.find(({ name }) => name === tableName);
  if (!table || tableName === 'backupStaging' || !Array.isArray(rows) || rows.length > MAX_RESTORE_DB_BATCH) {
    throw new Error(`Invalid restore batch for ${tableName}.`);
  }
  for (const row of rows) {
    if (!row || typeof row !== 'object' || Array.isArray(row)) throw new Error(`Invalid record in ${tableName}.`);
    const keyPath = table.schema.primKey.keyPath;
    const fields = Array.isArray(keyPath) ? keyPath : typeof keyPath === 'string' ? [keyPath] : [];
    for (const field of fields) {
      // Auto-increment key can be absent, but compound and non-auto keys cannot.
      if (!(field in row) && !table.schema.primKey.auto) throw new Error(`Missing ${tableName}.${field}.`);
    }
  }
}

export async function stageRestoreBatch(operationId: string, tableName: string, rows: unknown[]): Promise<void> {
  validateRestoreRows(tableName, rows);
  await db.backupStaging.add({ operationId, tableName, rows });
}

export async function discardRestoreStaging(operationId: string): Promise<void> {
  await db.backupStaging.where('operationId').equals(operationId).delete();
}

/** One Dexie transaction covers ALL affected tables; rejected bulkPut rolls back all clears/writes. */
export async function commitRestoreStaging(operationId: string, expected: readonly string[], signal?: AbortSignal): Promise<void> {
  validateRestoreTableNames(expected);
  const names = [...expected];
  const tables = db.tables.filter(({ name }) => name !== 'backupStaging');
  await db.transaction('rw', db.backupStaging, ...tables, async () => {
    // All app data not represented in the backup (e.g. caches) is invalidated too.
    for (const table of tables) await table.clear();
    for (const name of names) {
      let lastId = 0;
      while (true) {
        if (signal?.aborted) throw new DOMException('Restore cancelled', 'AbortError');
        const batch = await db.backupStaging.where('[operationId+tableName+id]')
          .between([operationId, name, lastId + 1], [operationId, name, Dexie.maxKey])
          .limit(1).toArray();
        if (!batch.length) break;
        const entry = batch[0];
        lastId = entry.id as number;
        if (entry.rows.length) await db.table(name).bulkPut(entry.rows);
      }
    }
    await db.backupStaging.where('operationId').equals(operationId).delete();
  });
}

export async function getStagedBookNames(operationId: string): Promise<string[]> {
  const names: string[] = [];
  await db.backupStaging.where('operationId').equals(operationId).each((entry) => {
    if (entry.tableName === 'books') {
      for (const row of entry.rows) {
        const name = (row as { opfsName?: unknown })?.opfsName;
        if (typeof name === 'string') names.push(name);
      }
    }
  });
  return names;
}

/** Only book names are needed for PDFs; never materialize all Book records. */
export async function countBookPdfs(): Promise<number> { return db.books.count(); }
export async function* readBookPdfNames(signal?: AbortSignal): AsyncGenerator<string> {
  let lastKey: IndexableType | undefined;
  while (true) {
    if (signal?.aborted) throw new DOMException('Cancelled', 'AbortError');
    const collection = lastKey === undefined ? db.books.orderBy(':id') : db.books.where(':id').above(lastKey);
    const [books, keys] = await Promise.all([
      collection.limit(BACKUP_DB_BATCH).toArray(),
      collection.limit(BACKUP_DB_BATCH).primaryKeys()
    ]);
    if (!books.length) break;
    lastKey = keys[keys.length - 1];
    for (const book of books) if (typeof book.opfsName === 'string') yield book.opfsName;
    if (books.length < BACKUP_DB_BATCH) break;
  }
}
